## Code Example

```javascript
// Minimal REST API for CAPA management
const express = require('express');
const app = express();

app.use(express.json());

// CAPA data storage (in production, use proper database)
let capas = {};

// POST /capas - Create new CAPA with evidence
app.post('/capas', (req, res) => {
  const capa = {
    id: Date.now().toString(),
    ...req.body,
    status: 'detected',
    createdAt: new Date().toISOString()
  };
  capas[capa.id] = capa;
  res.status(201).json(capa);
});

// PUT /capas/:id - Update existing CAPA
app.put('/capas/:id', (req, res) => {
  const id = req.params.id;
  if (!capas[id]) return res.status(404).json({error: 'CAPA not found'});

  capas[id] = {
    ...capas[id],
    ...req.body,
    updatedAt: new Date().toISOString()
  };
  res.json(capas[id]);
});

// PATCH /capas/:id/status - Update CAPA status
app.patch('/capas/:id/status', (req, res) => {
  const id = req.params.id;
  if (!capas[id]) return res.status(404).json({error: 'CAPA not found'});

  capas[id].status = req.body.status;
  capas[id].updatedAt = new Date().toISOString();
  res.json(capas[id]);
});

app.listen(3000, () => console.log('CAPA API running on port 3000'));
```
